// ADDING DATA INTO ARRAY OF OBJECTS WITHOUT EARSING OLDER DATA

const data2={name:'sampath'}

const server=http.createServer((req,res)=>{
    fs.readFile("./sample.js","utf-8",(err,data)=>{
        if(err){
            res.writeHead(500,{"content-type":"application/json"});
            res.write("error occured while entering into file")
            res.end()

        }
        else{
            const finalData=JSON.parse(data)
            
            const existing_user=finalData.find((user)=>user.name===data2.name);
            if(existing_user){
                res.writeHead(400,{"content-type":"application/json"});
                res.write("user already existed")
                res.end()
            }
            else{
                finalData.push(data2)
                fs.writeFile("./sample.js",JSON.stringify(finalData),(err,data)=>{
                    if(err){
                        res.writeHead(500,{"content-type":"application/json"});
                        res.write("error occured while inserting new data")
                        res.end()
                    }
                    else{
                        res.writeHead(200,{"content-type":"application/json"});
    
                        res.write(JSON.stringify(finalData))
                        res.end()
                    }
                })
            }
           
        }
    })
})
server.listen(port,()=>{
    console.log("server is up")
})